/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/rendering/00245c28.c, FUN_L00_002468b8. */
void initialize_render_archive_transfer(void) {
    s32 first_base;
    s32 second_base;
    s32 buffer;
    s32 bytes;
    s32 archive_index;
    RenderArchiveState *state = &map_menu_state;

    Profile_Mark();
    update_map_icons(state->archive_index, 1);
    first_base = level_menu_system.first_base;
    second_base = level_menu_system.second_base;
    buffer = first_base + 0x9a800;
    level_menu_system.first_base = buffer + 0x48000;
    map_menu_state.old_base = first_base;
    map_menu_state.start = 0;
    map_menu_state.buffer = buffer;
    map_menu_state.old_end = second_base;
    level_menu_system.second_base = second_base + 0x48000;
    state->zero_284 = 0;
    state->zero_288 = 0;
    state->slot_28c = -1;
    state->level_slot = -1;
    state->slot_294 = -1;
    state->slot_298 = -1;
    state->slot_29c = -1;
    state->slot_2a0 = -1;
    if (state->file_handle != -1) {
        if (state->loaded == 0 && gHaveMapOMatic != 0) {
            archive_index = state->archive_index;
            bytes = disc_table.render_archives[archive_index].size << 7;
            start_audio_stream_read(buffer, disc_table.render_archives[archive_index].sector,
                         disc_table.render_archives[archive_index].size);
            update_audio_stream_until_idle(1);
            state->loaded = 1;
            state->transfer_bytes = bytes;
            send_dma_to_stash_slot(state->buffer, state->file_handle, 0, bytes);
            state->level_slot = g_current_level_index + 0x100;
            state->last_transfer_bytes = bytes;
            state->active = 1;
            state->load_state = -2;
            return;
        }
        if (map_menu_state.file_handle != -1) {
            map_menu_state.last_transfer_bytes = map_menu_state.transfer_bytes;
            stash_receive_data(map_menu_state.buffer, map_menu_state.file_handle, 0, map_menu_state.transfer_bytes, 0);
            map_menu_state.level_slot = gHaveMapOMatic != 0 ? g_current_level_index + 0x100 : g_current_level_index;
            map_menu_state.active = 1;
            map_menu_state.load_state = -2;
            return;
        }
    }
    map_menu_state.active = 0;
}
